01064 static void find_coreGL(void) {
01065 
01066     /* Thank you @elmindreda
01067      * https://github.com/elmindreda/greg/blob/master/templates/greg.c.in#L176
01068      * https://github.com/glfw/glfw/blob/master/src/context.c#L36
01069      */
01070     int i, major, minor;
01071 
01072     const char* version;
01073     const char* prefixes[] = {
01074         "OpenGL ES-CM ",
01075         "OpenGL ES-CL ",
01076         "OpenGL ES ",
01077         NULL
01078     };
01079 
01080     version = (const char*) glGetString(GL_VERSION);
01081     if (!version) return;
01082 
01083     for (i = 0;  prefixes[i];  i++) {
01084         const size_t length = strlen(prefixes[i]);
01085         if (strncmp(version, prefixes[i], length) == 0) {
01086             version += length;
01087             break;
01088         }
01089     }
01090 
01091 /* PR #18 */
01092 #ifdef _MSC_VER
01093     sscanf_s(version, "%d.%d", &major, &minor);
01094 #else
01095     sscanf(version, "%d.%d", &major, &minor);
01096 #endif
01097 
01098     GLVersion.major = major; GLVersion.minor = minor;
01099     max_loaded_major = major; max_loaded_minor = minor;
01100     GLAD_GL_VERSION_1_0 = (major == 1 && minor >= 0) || major > 1;
01101     GLAD_GL_VERSION_1_1 = (major == 1 && minor >= 1) || major > 1;
01102     GLAD_GL_VERSION_1_2 = (major == 1 && minor >= 2) || major > 1;
01103     GLAD_GL_VERSION_1_3 = (major == 1 && minor >= 3) || major > 1;
01104     GLAD_GL_VERSION_1_4 = (major == 1 && minor >= 4) || major > 1;
01105     GLAD_GL_VERSION_1_5 = (major == 1 && minor >= 5) || major > 1;
01106     GLAD_GL_VERSION_2_0 = (major == 2 && minor >= 0) || major > 2;
01107     GLAD_GL_VERSION_2_1 = (major == 2 && minor >= 1) || major > 2;
01108     GLAD_GL_VERSION_3_0 = (major == 3 && minor >= 0) || major > 3;
01109     GLAD_GL_VERSION_3_1 = (major == 3 && minor >= 1) || major > 3;
01110     GLAD_GL_VERSION_3_2 = (major == 3 && minor >= 2) || major > 3;
01111     GLAD_GL_VERSION_3_3 = (major == 3 && minor >= 3) || major > 3;
01112     if (GLVersion.major > 3 || (GLVersion.major >= 3 && GLVersion.minor >= 3)) {
01113         max_loaded_major = 3;
01114         max_loaded_minor = 3;
01115     }
01116 }
01117 
01118 int gladLoadGLLoader(GLADloadproc load) {
01119     GLVersion.major = 0; GLVersion.minor = 0;
01120     glGetString = (PFNGLGETSTRINGPROC)load("glGetString");
01121     if(glGetString == NULL) return 0;
01122     if(glGetString(GL_VERSION) == NULL) return 0;
01123     find_coreGL();
01124     load_GL_VERSION_1_0(load);
01125     load_GL_VERSION_1_1(load);
01126     load_GL_VERSION_1_2(load);
01127     load_GL_VERSION_1_3(load);
01128     load_GL_VERSION_1_4(load);
01129     load_GL_VERSION_1_5(load);
01130     load_GL_VERSION_2_0(load);
01131     load_GL_VERSION_2_1(load);
01132     load_GL_VERSION_3_0(load);
01133     load_GL_VERSION_3_1(load);
01134     load_GL_VERSION_3_2(load);
01135     load_GL_VERSION_3_3(load);
01136 
01137     if (!find_extensionsGL()) return 0;
01138     return GLVersion.major != 0 || GLVersion.minor != 0;
01139 }
